package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_siblingElements_TriageGen2Test {

    @Test
    public void testSiblingElementsWithMultipleChildren() {
        String html = "<html><body><div id='parent'><p id='child1'></p><p id='child2'></p><p id='child3'></p></div></body></html>";
        Document doc = Parser.parse(html);
        Element parent = doc.selectFirst("#parent");
        Element child1 = doc.selectFirst("#child1");

        Elements siblings = child1.siblingElements();

        // According to the implementation: return parent().children();
        // This means it returns ALL children of the parent, not just siblings excluding self.
        Assert.assertEquals(3, siblings.size());
        Assert.assertTrue(siblings.contains(child1));
        Assert.assertTrue(siblings.contains(doc.selectFirst("#child2")));
        Assert.assertTrue(siblings.contains(doc.selectFirst("#child3")));
    }

    @Test
    public void testSiblingElementsWithSingleChild() {
        String html = "<html><body><div id='parent'><p id='child1'></p></div></body></html>";
        Document doc = Parser.parse(html);
        Element parent = doc.selectFirst("#parent");
        Element child1 = doc.selectFirst("#child1");

        Elements siblings = child1.siblingElements();

        Assert.assertEquals(1, siblings.size());
        Assert.assertEquals(child1, siblings.get(0));
    }

    @Test
    public void testSiblingElementsWithNoChildren() {
        // This case is technically impossible if the element itself is a child, 
        // but we test the logic via a detached element or an empty parent scenario.
        Document doc = Document.createShell();
        Element parent = doc.appendElement("div");
        Element child = parent.appendElement("p");
        parent.empty(); // Remove child

        // If we manually force a child that is not in parent, but the method calls parent().children()
        // We simulate the state where the element exists but its parent's children list is empty 
        // (though in Jsoup, an element is usually in its parent's child list).

        // Let's test a standard detached element
        Element detached = new Element(Tag.valueOf("p"), "");
        // detached.parent() is null. Calling siblingElements() should throw NullPointerException 
        // because parent() returns null.
        try {
            detached.siblingElements();
            Assert.fail("Should have thrown NullPointerException because parent() is null");
        } catch (NullPointerException e) {
            // Success
        }
    }

    @Test
    public void testSiblingElementsReturnsAllChildrenOfParent() {
        String html = "<ul id='list'><li>1</li><li>2</li><li>3</li></ul>";
        Document doc = Parser.parse(html);
        Element ul = doc.selectFirst("#list");
        Element li2 = ul.child(1);

        Elements siblings = li2.siblingElements();

        // Verify it returns the exact list of children from the parent
        Assert.assertEquals(ul.children(), siblings);
        Assert.assertEquals(3, siblings.size());
        Assert.assertEquals("1", siblings.get(0).text());
        Assert.assertEquals("2", siblings.get(1).text());
        Assert.assertEquals("3", siblings.get(2).text());
    }
}
